import{_ as t,o as d,c as a,Q as r}from"./chunks/framework.48927342.js";const p=JSON.parse('{"title":"回复婚礼邀请邮件","description":"","frontmatter":{},"headers":[],"relativePath":"zh/more/maltese/practice/emails/04-wedding-reply.md","filePath":"zh/more/maltese/practice/emails/04-wedding-reply.md"}'),e={name:"zh/more/maltese/practice/emails/04-wedding-reply.md"},o=r('<h1 id="回复婚礼邀请邮件" tabindex="-1">回复婚礼邀请邮件 <a class="header-anchor" href="#回复婚礼邀请邮件" aria-label="Permalink to &quot;回复婚礼邀请邮件&quot;">​</a></h1><p><strong>场景：</strong> 一位受邀者回复新人，确认自己和配偶会出席婚礼。</p><h2 id="邮件头部" tabindex="-1">邮件头部 <a class="header-anchor" href="#邮件头部" aria-label="Permalink to &quot;邮件头部&quot;">​</a></h2><p><strong>Lil（收件人 To）：</strong> <a href="mailto:anna.c@gmail.com" target="_blank" rel="noreferrer">anna.c@gmail.com</a><strong>Mingħand（发件人 From）：</strong> <a href="mailto:david.b@gmail.com" target="_blank" rel="noreferrer">david.b@gmail.com</a><strong>Data（日期）：</strong> 25 ta&#39; Ġunju 2026 <strong>Suġġett（主题）：</strong> Risposta għall-istedina tat-tieġ</p><h2 id="邮件全文" tabindex="-1">邮件全文 <a class="header-anchor" href="#邮件全文" aria-label="Permalink to &quot;邮件全文&quot;">​</a></h2><blockquote><p><strong>Lil:</strong> <a href="mailto:anna.c@gmail.com" target="_blank" rel="noreferrer">anna.c@gmail.com</a><strong>Mingħand:</strong> <a href="mailto:david.b@gmail.com" target="_blank" rel="noreferrer">david.b@gmail.com</a><strong>Data:</strong> 25 ta&#39; Ġunju 2026 <strong>Suġġett:</strong> Risposta għall-istedina tat-tieġ</p><p>Għeżież Anna u Mark,</p><p>Grazzi tal-istedina għat-tieġ tagħkom.</p><p>Ninsabu kuntenti li nikkonfermaw li se nattendu.</p><p>Jien u marti se niġu għaċ-ċerimonja u għar-riċeviment.</p><p>Naslu fil-ħin.</p><p>Għandna nġibu xi ħaġa għalikom?</p><p>Nawguralkom ħafna hena u mħabba fil-ħajja miżżewġa tagħkom.</p><p>Nistennew bil-ħerqa li niċċelebraw magħkom.</p><p>Grazzi mill-ġdid. Tislijiet, David</p></blockquote><h2 id="逐句翻译与逐词拆解" tabindex="-1">逐句翻译与逐词拆解 <a class="header-anchor" href="#逐句翻译与逐词拆解" aria-label="Permalink to &quot;逐句翻译与逐词拆解&quot;">​</a></h2><p><strong>Malti:</strong> Lil: <a href="mailto:anna.c@gmail.com" target="_blank" rel="noreferrer">anna.c@gmail.com</a></p><p><strong>整句：</strong> 收件人（To）：anna.c@gmail.com</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Lil</td><td>收件人；给……</td><td>邮件头部&quot;To&quot;的马耳他语标签</td></tr><tr><td><a href="mailto:anna.c@gmail.com" target="_blank" rel="noreferrer">anna.c@gmail.com</a></td><td>邮箱地址</td><td>收件人（Anna）的邮箱</td></tr></tbody></table><p><strong>Malti:</strong> Mingħand: <a href="mailto:david.b@gmail.com" target="_blank" rel="noreferrer">david.b@gmail.com</a></p><p><strong>整句：</strong> 发件人（From）：david.b@gmail.com</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Mingħand</td><td>发件人；来自……</td><td>邮件头部&quot;From&quot;的马耳他语标签，本义&quot;从……那里&quot;</td></tr><tr><td><a href="mailto:david.b@gmail.com" target="_blank" rel="noreferrer">david.b@gmail.com</a></td><td>邮箱地址</td><td>发件人（David）的邮箱</td></tr></tbody></table><p><strong>Malti:</strong> Data: 25 ta&#39; Ġunju 2026</p><p><strong>整句：</strong> 日期：2026 年 6 月 25 日</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Data</td><td>日期</td><td>邮件头部&quot;Date&quot;；马耳他语日期格式为&quot;日 ta&#39; 月 年&quot;</td></tr><tr><td>25</td><td>二十五</td><td>日期中的日</td></tr><tr><td>ta&#39;</td><td>……的</td><td>连接日和月份</td></tr><tr><td>Ġunju</td><td>六月</td><td>月份名</td></tr></tbody></table><p><strong>Malti:</strong> Suġġett: Risposta għall-istedina tat-tieġ</p><p><strong>整句：</strong> 主题：回复婚礼邀请</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Suġġett</td><td>主题</td><td>邮件头部&quot;Subject&quot;</td></tr><tr><td>Risposta</td><td>回复；答复</td><td>阴性名词</td></tr><tr><td>għall-istedina</td><td>针对邀请；回应邀请</td><td><code>għal</code> + <code>l-istedina</code> 的缩合形式</td></tr><tr><td>tat-tieġ</td><td>婚礼的</td><td><code>ta&#39;</code> + <code>it-tieġ</code> 的缩合形式</td></tr></tbody></table><p><strong>Malti:</strong> Għeżież Anna u Mark,</p><p><strong>整句：</strong> 亲爱的安娜和马克：</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Għeżież</td><td>亲爱的</td><td>阳性复数称呼形式</td></tr><tr><td>Anna</td><td>安娜</td><td>人名</td></tr><tr><td>u</td><td>和</td><td>连词</td></tr><tr><td>Mark</td><td>马克</td><td>人名</td></tr></tbody></table><h3 id="_1" tabindex="-1">1. <a class="header-anchor" href="#_1" aria-label="Permalink to &quot;1.&quot;">​</a></h3><p><strong>Malti:</strong> Grazzi tal-istedina għat-tieġ tagħkom.</p><p><strong>整句：</strong> 感谢你们邀请我们参加婚礼。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Grazzi</td><td>谢谢</td><td>礼貌用语</td></tr><tr><td>tal-istedina</td><td>因为邀请；邀请的</td><td><code>ta&#39; + l-istedina</code> 的缩合形式</td></tr><tr><td>għat-tieġ</td><td>去婚礼；参加婚礼</td><td><code>għal</code> + <code>it-tieġ</code> 的缩合形式</td></tr><tr><td>tagħkom</td><td>你们的</td><td>第二人称复数所有格</td></tr></tbody></table><h3 id="_2" tabindex="-1">2. <a class="header-anchor" href="#_2" aria-label="Permalink to &quot;2.&quot;">​</a></h3><p><strong>Malti:</strong> Ninsabu kuntenti li nikkonfermaw li se nattendu.</p><p><strong>整句：</strong> 我们很高兴确认会出席。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Ninsabu</td><td>我们处于；我们感到</td><td>第一人称复数形式</td></tr><tr><td>kuntenti</td><td>高兴的</td><td>复数形式</td></tr><tr><td>li</td><td>……；引出从句</td><td>连词</td></tr><tr><td>nikkonfermaw</td><td>我们确认</td><td>第一人称复数形式</td></tr><tr><td>li</td><td>……；引出从句</td><td>连词</td></tr><tr><td>se</td><td>将；会</td><td>将来标记</td></tr><tr><td>nattendu</td><td>我们出席</td><td>第一人称复数形式</td></tr></tbody></table><h3 id="_3" tabindex="-1">3. <a class="header-anchor" href="#_3" aria-label="Permalink to &quot;3.&quot;">​</a></h3><p><strong>Malti:</strong> Jien u marti se niġu għaċ-ċerimonja u għar-riċeviment.</p><p><strong>整句：</strong> 我和我妻子会参加仪式和宴会。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Jien</td><td>我</td><td>强调代词</td></tr><tr><td>u</td><td>和</td><td>连词</td></tr><tr><td>marti</td><td>我的妻子</td><td><code>mara</code>“妻子/女人” + 第一人称所有格形式</td></tr><tr><td>se</td><td>将；会</td><td>将来标记</td></tr><tr><td>niġu</td><td>我们来</td><td>第一人称复数形式</td></tr><tr><td>għaċ-ċerimonja</td><td>去仪式；参加仪式</td><td><code>għal</code> + <code>iċ-ċerimonja</code> 的缩合形式</td></tr><tr><td>u</td><td>和</td><td>连词</td></tr><tr><td>għar-riċeviment</td><td>去宴会；参加宴会</td><td><code>għal</code> + <code>ir-riċeviment</code> 的缩合形式</td></tr></tbody></table><h3 id="_4" tabindex="-1">4. <a class="header-anchor" href="#_4" aria-label="Permalink to &quot;4.&quot;">​</a></h3><p><strong>Malti:</strong> Naslu fil-ħin.</p><p><strong>整句：</strong> 我们会准时到。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Naslu</td><td>我们到达</td><td>第一人称复数形式；此处表达将来安排</td></tr><tr><td>fil-ħin</td><td>准时；在时间内</td><td><code>f&#39;</code> + <code>il-ħin</code> 的缩合形式</td></tr></tbody></table><h3 id="_5" tabindex="-1">5. <a class="header-anchor" href="#_5" aria-label="Permalink to &quot;5.&quot;">​</a></h3><p><strong>Malti:</strong> Għandna nġibu xi ħaġa għalikom?</p><p><strong>整句：</strong> 我们需要给你们带些什么吗？</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Għandna</td><td>我们有；我们需要</td><td>第一人称复数形式；与后续动词连用可表达需要/应该</td></tr><tr><td>nġibu</td><td>我们带来</td><td>第一人称复数形式</td></tr><tr><td>xi</td><td>一些；什么</td><td>疑问句中表示“什么”</td></tr><tr><td>ħaġa</td><td>东西</td><td>阴性名词</td></tr><tr><td>għalikom</td><td>给你们；为了你们</td><td><code>għal</code>“给” + <code>-kom</code>“你们”</td></tr></tbody></table><h3 id="_6" tabindex="-1">6. <a class="header-anchor" href="#_6" aria-label="Permalink to &quot;6.&quot;">​</a></h3><p><strong>Malti:</strong> Nawguralkom ħafna hena u mħabba fil-ħajja miżżewġa tagħkom.</p><p><strong>整句：</strong> 祝你们婚后生活幸福美满、充满爱意。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Nawguralkom</td><td>我祝愿你们</td><td><code>nawgura</code>“我祝愿” + <code>-lkom</code>“你们”</td></tr><tr><td>ħafna</td><td>很多；非常</td><td>程度/数量词</td></tr><tr><td>hena</td><td>幸福；快乐</td><td>阳性名词</td></tr><tr><td>u</td><td>和</td><td>连词</td></tr><tr><td>mħabba</td><td>爱</td><td>阴性名词</td></tr><tr><td>fil-ħajja</td><td>在生活中</td><td><code>f&#39;</code> + <code>il-ħajja</code> 的缩合形式</td></tr><tr><td>miżżewġa</td><td>已婚的</td><td>阴性形式，与 <code>ħajja</code> 一致</td></tr><tr><td>tagħkom</td><td>你们的</td><td>第二人称复数所有格</td></tr></tbody></table><h3 id="_7" tabindex="-1">7. <a class="header-anchor" href="#_7" aria-label="Permalink to &quot;7.&quot;">​</a></h3><p><strong>Malti:</strong> Nistennew bil-ħerqa li niċċelebraw magħkom.</p><p><strong>整句：</strong> 我们期待和你们一起庆祝。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Nistennew</td><td>我们等待；我们期待</td><td>第一人称复数形式</td></tr><tr><td>bil-ħerqa</td><td>热切地；期待地</td><td>固定副词短语</td></tr><tr><td>li</td><td>……；引出从句</td><td>连词</td></tr><tr><td>niċċelebraw</td><td>我们庆祝</td><td>第一人称复数形式</td></tr><tr><td>magħkom</td><td>和你们一起</td><td><code>ma&#39;</code>“和” + <code>-kom</code>“你们”</td></tr></tbody></table><p><strong>Malti:</strong> Grazzi mill-ġdid. Tislijiet, David</p><p><strong>整句：</strong> 再次感谢。此致敬意，大卫。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Grazzi</td><td>谢谢</td><td>礼貌用语</td></tr><tr><td>mill-ġdid</td><td>再一次</td><td><code>minn</code> + <code>il-ġdid</code> 的固定缩合表达</td></tr><tr><td>Tislijiet</td><td>此致敬意；致以问候</td><td>正式邮件/信件落款用语，本义&quot;问候/致意&quot;</td></tr><tr><td>David</td><td>大卫</td><td>人名</td></tr></tbody></table>',53),i=[o];function n(l,h,s,g,c,m){return d(),a("div",null,i)}const u=t(e,[["render",n]]);export{p as __pageData,u as default};
